750:   function keepEspressoSectionRendered(hostId, markerSelector, renderFn) {
751:     const host = document.getElementById(hostId);
752:     if (!host) {
753:       return;
754:     }
755: 
756:     let isUpdating = false;
757:     const apply = () => {
758:       if (isUpdating || host.querySelector(markerSelector)) {
759:         return;
760:       }
761:       isUpdating = true;
762:       renderFn(host);
763:       isUpdating = false;
764:     };
765: 
766:     const observer = new MutationObserver(() => {
767:       if (!host.querySelector(markerSelector)) {
768:         apply();
769:         observer.disconnect();
770:       }
771:     });
772: 
773:     observer.observe(host, { childList: true });
774:     apply();
775: 
776:     window.addEventListener("load", () => {
777:       apply();
778:       observer.disconnect();
779:     }, { once: true });
780:   }
